/* Decide what an incoming prompt does: a normal reply, an A2UI surface, or an interrupt. */
window.planAgent = function planAgent(agent, prompt) {
  const hil = window.AGENT_HIL[agent.id];
  const p = (prompt || "").toLowerCase();
  const a2uiTriggers = ["schedule", "meeting", "calendar", "book", "reserve", "form", "예약", "일정", "회의"];
  if (a2uiTriggers.some(t => p.includes(t))) {
    return {
      type: "a2ui",
      surface: window.buildScheduleSurface(prompt)
    };
  }
  if (hil && hil.triggers.some(t => p.includes(t))) {
    return {
      type: "interrupt",
      approver: hil.approver,
      permission: hil.permission,
      tool: hil.tool,
      args: hil.makeArgs(prompt),
      summary: hil.summarize(prompt),
      checkpoint: nextCheckpoint(agent.id)
    };
  }
  return {
    type: "reply",
    ...window.runAgent(agent, prompt)
  };
};

/* Build the reply + trace produced when a paused run resumes from its checkpoint. */
window.resumeAgent = function resumeAgent(agent, interruptInfo, decision) {
  const base = window.runAgent(agent, interruptInfo.summary);
  if (decision === "reject") {
    base.text = "알겠습니다 — '" + interruptInfo.summary + "' 작업은 실행하지 않겠습니다. " + interruptInfo.checkpoint + " 체크포인트에서 중단되었고, 아무것도 실행되지 않았습니다.";
  } else {
    base.text = "승인되었습니다. " + interruptInfo.checkpoint + "에서 재개해 " + interruptInfo.tool + "을(를) 실행했습니다. '" + interruptInfo.summary + "' — 완료.";
    base.trace.mcp = [{
      server: interruptInfo.tool.split(".")[0],
      tool: interruptInfo.tool.split(".")[1] || "call",
      status: "ok",
      ms: 320,
      args: interruptInfo.args,
      result: "ok"
    }];
  }
  base.trace.graph = [{
    node: "resume",
    ms: 0
  }, {
    node: "checkpoint_load",
    ms: 24
  }, ...(decision === "approve" ? [{
    node: "tools",
    ms: 320
  }] : []), {
    node: "call_model",
    ms: 540 + Math.round(Math.random() * 300)
  }, {
    node: "__end__",
    ms: 14
  }];
  base.trace.resumedFrom = interruptInfo.checkpoint;
  base.trace.latencyMs = base.trace.graph.reduce((a, c) => a + c.ms, 0);
  return base;
};

